class Solution {
public:
    string smallestString(string s) {
        int n = s.size();
        int i = 0;
        while (i < n && s[i] == 'a') ++i;
        if (i == n) {
            s.back() = 'z';
            return s;
        }
        while (i < n && s[i] != 'a') {
            s[i]--;
            ++i;
        }
        return s;
    }
};

class Solution {
    public String smallestString(String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;
        int i = 0;
        while (i < n && chars[i] == 'a') i++;
        if (i == n) {
            chars[n - 1] = 'z';
            return new String(chars);
        }
        while (i < n && chars[i] != 'a') {
            chars[i]--;
            i++;
        }
        return new String(chars);
    }
}

var smallestString = function(s) {
    const chars = s.split("");
    const n = chars.length;
    let i = 0;
    while (i < n && chars[i] === 'a') i++;
    if (i === n) {
        chars[n - 1] = 'z';
        return chars.join("");
    }
    while (i < n && chars[i] !== 'a') {
        chars[i] = String.fromCharCode(chars[i].charCodeAt(0) - 1);
        i++;
    }
    return chars.join("");
};
